import type { INestApplication } from '@nestjs/common';
import { PugEngine } from '@nestvexa/engine-pug';
import { registerViewEngine } from 'nestvexa';
import { resolve } from 'node:path';

/**
 * Generated by `nestvexa add engine pug`. Views ending in `.pug` under
 * views/ render with this adapter (`@Render('pages/home.pug')`); `.hbs`
 * views keep using the default Handlebars engine.
 */
export const pugEngine = new PugEngine({
  root: resolve(process.cwd(), 'views'),
  cache: process.env['NODE_ENV'] === 'production',
  defaultLayout: 'layouts/main',
});

/**
 * Registers the `.pug` view engine on Express or Fastify. Call before
 * `app.listen()`; dispose the engine on shutdown if you create it per test.
 */
export async function registerPugEngine(app: INestApplication): Promise<void> {
  await registerViewEngine(app, 'pug', pugEngine);
}
